class _LiveServerServerHandler(ServerHandler):
    """A ServerHandler that disables HTTP persistent connections.

    LiveServerTestCase runs a test server in a background thread.
    ThreadedWSGIServer handles each client connection in a separate thread. If
    HTTP keep-alive is enabled, those threads can outlive the test case's
    teardown and keep database connections open.

    Disable keep-alive to ensure worker threads terminate after each request.
    """

    def cleanup_headers(self):
        super().cleanup_headers()
        # Always close the connection so that each request is served in a fresh
